<?php
require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/functions.php';require_once __DIR__ . '/legal_library.php';$pdo=aep_database();$id=(int)($_GET['id']??0);$stmt=$pdo->prepare('SELECT m.*,c.name client_name,c.client_reference FROM matters m JOIN clients c ON c.id=m.client_id WHERE m.id=?');$stmt->execute([$id]);$matter=$stmt->fetch();if(!$matter){http_response_code(404);exit('Matter not found.');}$stmt=$pdo->prepare('SELECT * FROM tasks WHERE matter_id=? ORDER BY COALESCE(due_date,"9999-12-31"),created_at DESC');$stmt->execute([$id]);$tasks=$stmt->fetchAll();$stmt=$pdo->prepare('SELECT * FROM deadlines WHERE matter_id=? AND status!="completed" ORDER BY due_date');$stmt->execute([$id]);$deadlines=$stmt->fetchAll();$pageTitle='Matter | AEP';$activeNav='matters';require __DIR__.'/includes/header.php';?>
<div class="actions" style="justify-content:space-between"><div><span class="badge"><?php echo aep_h($matter['matter_reference']);?></span><h1 style="margin:8px 0"><?php echo aep_h($matter['subject']);?></h1><p class="muted"><a href="client_view.php?id=<?php echo (int)$matter['client_id'];?>"><?php echo aep_h($matter['client_name']);?></a> · <?php echo aep_h($matter['practice_area']);?> · <?php echo aep_h($matter['status']);?></p></div><div class="actions"><a class="btn secondary" href="matter_edit.php?id=<?php echo $id;?>">Edit</a><a class="btn" href="counsel_engine.php?domain=<?php echo urlencode(array_search($matter['practice_area'],array_column(aep_domain_profiles(),'label'),true)?:'commercial_law');?>">Open Counsel Engine</a></div></div>
<div class="grid grid-2" style="margin-top:18px"><section class="card"><div class="actions" style="justify-content:space-between"><h2>Tasks</h2><a class="btn secondary" href="task_create.php?matter_id=<?php echo $id;?>">Add task</a></div><?php if(!$tasks):?><div class="empty">Ready to create the first task.</div><?php else:?><ul><?php foreach($tasks as $task):?><li><a href="task_view.php?id=<?php echo (int)$task['id'];?>"><?php echo aep_h($task['title']);?></a> <span class="badge"><?php echo aep_h($task['status']);?></span></li><?php endforeach;?></ul><?php endif;?></section><section class="card"><div class="actions" style="justify-content:space-between"><h2>Deadlines</h2><a class="btn secondary" href="deadline_create.php?matter_id=<?php echo $id;?>">Add deadline</a></div><?php if(!$deadlines):?><div class="empty">No open deadlines recorded.</div><?php else:?><ul><?php foreach($deadlines as $deadline):?><li><strong><?php echo aep_h($deadline['due_date']);?></strong> — <?php echo aep_h($deadline['title']);?> <span class="badge"><?php echo aep_h($deadline['priority']);?></span></li><?php endforeach;?></ul><?php endif;?></section></div><?php require __DIR__.'/includes/footer.php';?>
